{"sql": "-- Create monthly_reports table
CREATE TABLE IF NOT EXISTS employees.monthly_reports (
    report_id SERIAL PRIMARY KEY,
    report_date DATE NOT NULL,
    department_count INTEGER NOT NULL,
    total_employees INTEGER NOT NULL,
    avg_salary DECIMAL(10, 2) NOT NULL,
    generated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create stored procedure for report generation
CREATE OR REPLACE FUNCTION employees.generate_monthly_report(report_date DATE)
RETURNS INTEGER AS $$
DECLARE
    v_report_id INTEGER;
    v_dept_count INTEGER;
    v_total_employees INTEGER;
    v_avg_salary DECIMAL(10, 2);
BEGIN
    -- Calculate department count
    SELECT COUNT(DISTINCT dept_no) INTO v_dept_count
    FROM employees.departments;

    -- Calculate total active employees (current)
    SELECT COUNT(DISTINCT emp_no) INTO v_total_employees
    FROM employees.salaries
    WHERE to_date = '9999-01-01';

    -- Calculate average salary for active employees
    SELECT ROUND(AVG(salary)::numeric, 2) INTO v_avg_salary
    FROM employees.salaries
    WHERE to_date = '9999-01-01';

    -- Insert the report
    INSERT INTO employees.monthly_reports (
        report_date, 
        department_count, 
        total_employees, 
        avg_salary,
        generated_at
    )
    VALUES (
        report_date,
        v_dept_count,
        v_total_employees,
        v_avg_salary,
        CURRENT_TIMESTAMP
    )
    RETURNING report_id INTO v_report_id;

    RETURN v_report_id;
END;
$$ LANGUAGE plpgsql;"}

